type DeliveryStatus = 'sending' | 'sent' | 'failed';
type SendResult = { ok: true } | { ok: false; retryable: boolean; error: string };

interface Provider {
  send(recipient: string, body: string): Promise<SendResult>;
}
interface NotificationStore {
  getStatus(key: string): Promise<DeliveryStatus | undefined>;
  setStatus(key: string, status: DeliveryStatus): Promise<void>;
}
const delay = (ms: number) => new Promise<void>(resolve => setTimeout(resolve, ms));

class DeliveryService {
  constructor(private primary: Provider, private backup: Provider, private store: NotificationStore) {}

  async deliver(key: string, recipient: string, body: string): Promise<DeliveryStatus> {
    const current = await this.store.getStatus(key);
    if (current === 'sent' || current === 'sending') return current;

    await this.store.setStatus(key, 'sending');
    for (let attempt = 1; attempt <= 3; attempt++) {
      const result = await this.primary.send(recipient, body);
      if (result.ok) {
        await this.store.setStatus(key, 'sent');
        return 'sent';
      }
      if (!result.retryable) break;
      if (attempt < 3) await delay(500 * 2 ** (attempt - 1));
    }

    const fallback = await this.backup.send(recipient, body);
    const finalStatus: DeliveryStatus = fallback.ok ? 'sent' : 'failed';
    await this.store.setStatus(key, finalStatus);
    return finalStatus;
  }
}
